        if (setsockopt(rsock, SOL_SOCKET, SO_RCVTIMEO,
                &tv, sizeof(tv)) < 0) {
            syslog(LOG_WARNING,
                "[%s] set SO_RCVTIMEO failed, errno=%d\n", TAG, errno);
        } else {
            syslog(LOG_INFO,
                "[%s] recorder socket recv timeout = 200ms\n", TAG);
        }
    }
}

