/* 回一个 PONG（控制帧）。服务端发 PING 保活，不回的话对端可能断开连接。 */
static int ws_send_pong(asr_tls_ctx_t* ctx,
    const unsigned char* payload, size_t plen)
{
    unsigned char hdr[14];
    size_t hdr_len;

    hdr[0] = WS_FIN_BIT | WS_OPCODE_PONG;

    if (plen < 126) {
        hdr[1] = WS_MASK_BIT | (unsigned char)plen;
        hdr_len = 2;
    } else {
        hdr[1] = WS_MASK_BIT | 126;
        hdr[2] = (unsigned char)(plen >> 8);
        hdr[3] = (unsigned char)(plen & 0xFF);
        hdr_len = 4;
    }

    if (plen > 125) {
        /* 控制帧载荷按 RFC 不允许超过 125，超了就直接放弃回包 */
        return 0;
    }

    unsigned char mask[WS_MASK_KEY_LEN];

    asr_entropy_func(NULL, mask, WS_MASK_KEY_LEN);
    memcpy(hdr + hdr_len, mask, WS_MASK_KEY_LEN);
    hdr_len += WS_MASK_KEY_LEN;

    int ret = tls_write_all(ctx, hdr, hdr_len);

    if (ret != 0) {
        return ret;
    }

    unsigned char chunk[128];
    size_t i;

    for (i = 0; i < plen; i++) {
        chunk[i] = payload[i] ^ mask[i % WS_MASK_KEY_LEN];
    }

    return plen > 0 ? tls_write_all(ctx, chunk, plen) : 0;
}

