        syslog(LOG_INFO, "[%s] WS ping, replying pong\n", TAG);
        ws_send_pong(ctx, buf, flen);
        continue;
    }

    if (opcode == WS_OPCODE_PONG) {
        continue;
    }

    break;
}

if (opcode == WS_OPCODE_CLOSE) {
    syslog(LOG_WARNING, "[%s] Server sent WS close\n", TAG);
    free(buf);
    return -ECONNRESET;
